	if config == nil {
		t.Fatal("Could not bootstrap config.")
	}

	parent := fmt.Sprintf("projects/%s/locations/%s/odbNetworks/%s", project, location, odbNetworkId)
	name := fmt.Sprintf("%s/odbDnsZones/%s", parent, odbDnsZoneId)
